export const SKILL_FILES: Record<string, string> = {
  "releases-mcp/SKILL.md": "---\nname: releases-mcp\ndescription: Use when the user asks about recent releases, changelogs, what's new in a library, breaking changes, version updates, or wants to compare products. Activates for questions like \"what changed in Next.js 15?\", \"latest Tailwind releases\", \"compare Bun vs Deno releases\".\n---\n\n# Release Notes Index — Changelog Lookup\n\nWhen the user asks about releases, changelogs, or version updates, use the Releases Index MCP tools to fetch current data instead of relying on training data. Training data is stale for fast-moving libraries; these tools read the live registry.\n\n## When to Use This Skill\n\nActivate when the user:\n\n- Asks what's new or changed in a library/product (\"What changed in Next.js 15?\")\n- Wants recent releases or changelogs (\"Show me the latest Tailwind releases\")\n- Asks about breaking changes or migration (\"Were there breaking changes in Prisma 6?\")\n- Wants to compare release activity between products (\"Compare Bun vs Deno releases\")\n- Mentions version updates, release notes, or changelogs for a specific product\n- Asks about a curated topic feed (\"what's new across the AI labs?\")\n\n## The Tools\n\nThe hosted server exposes these tools. There is no AI summarization or comparison tool — you synthesize those yourself from the data below.\n\n- `search` — unified search across four sections: orgs, catalog (products + standalone sources), collections, and releases. Your default entry point.\n- `get_latest_releases` — recent releases, optionally scoped by `organization` or `product`. Use `since` / `until` for time windows.\n- `list_organizations` / `get_organization` — browse and inspect orgs.\n- `list_catalog` / `get_catalog_entry` — browse and inspect catalog entries. Each entry carries `entryType: \"product\" | \"source\"`. `get_catalog_entry` also serves CHANGELOG slices (see below).\n- `get_release` — fetch one release in full by its `rel_` id (ids come from `search` / `get_latest_releases`).\n- `list_collections` / `get_collection` / `get_collection_releases` — curated cross-org \"playlists\" (e.g. \"Frontier AI Labs\", \"Coding Agents\") independent of the category taxonomy.\n- `lookup_domain` — resolve a URL/domain to the org that owns it. Use when you have a URL-shaped input rather than a name.\n- `whats_changed` (**beta**) — the changelog entries between two versions of a package: `whats_changed(package, from, to)` returns the releases in `(from, to]` with summaries, breaking-change verdicts, and migration notes. Use it to plan an upgrade instead of reading many changelog pages. `package` is a tracked source slug or a GitHub `owner/repo`. No sign-in needed.\n\nThe server also exposes **signed-in account tools**. They act on the user's own account, need an authenticated connection (a \"Sign in with Releases\" OAuth token or a `relu_` user API key), and return an error for anonymous clients. The reader tools above need no auth.\n\n- `follow` / `unfollow` / `list_follows` and `get_personalized_feed` — the user's follows and their feed. Reach for these only when the user asks about *their* follows or feed. For general \"what's new in X\" questions, the reader tools answer without sign-in.\n- `list_webhooks` (read-only) and `manage_webhook` (`create` / `update` / `delete` / `test` / `rotate_secret`) — the user's release webhooks. Pass `workspace` (an id or slug) to work on a shared workspace's webhooks instead; `list_webhooks` with no `workspace` also lists the user's workspaces. Workspace owners and admins can change workspace webhooks; members can list and test them. Workspace webhooks target one org (no follows scope). `create` needs `format` (`json`, `slack`, or `discord`). A `json` webhook's signing key is shown only once, on create or rotate — tell the user to store it right away. Slack and Discord webhooks have no signing key. Only create, change, or delete a webhook when the user asks for it.\n\n## How to Look Up Releases\n\n### Step 1: Resolve the entity\n\nStart with `search` and the product or company name — it returns orgs, catalog, collections, and releases in one call, so you usually don't need a separate lookup. Narrow with `type` (e.g. `type: [\"catalog\"]` for a fast registry-only lookup, `type: [\"releases\"]` for pure release content).\n\nIf a name doesn't resolve, try variations:\n\n- The company instead of the product (\"Vercel\" rather than \"Next.js\")\n- The GitHub org (\"supabase\")\n- A domain — or use `lookup_domain` directly (e.g. \"tailwindcss.com\")\n- A `{org}/{repo}` GitHub coordinate (\"vercel/next.js\"). When nothing matches a coordinate-shaped query, the registry probes GitHub on demand and the response carries a `lookup` field with status `indexed` / `existing` / `empty` / `not_found` / `deferred`. Coordinate matching is case-insensitive.\n\n### Step 2: Pick the right follow-up\n\n- **\"What's new?\" / \"Latest releases\"** → `get_latest_releases` with `organization` or `product`. Add `since` (e.g. `\"30d\"`, `\"6m\"`, or an ISO date) for \"last month\" / \"since v4\" style asks.\n- **Keyword across the whole registry** → `search` with a descriptive query; narrow with `type`.\n- **One release in full** (to quote a note verbatim) → `get_release` with the `rel_` id from search results.\n- **Entity metadata** → `get_catalog_entry` (products/sources) or `get_organization` (orgs, with an AI overview preview; `include_overview: true` for the full briefing).\n- **Full maintained CHANGELOG.md** → `get_catalog_entry` with `include_changelog: true`. This only applies to **source** entries that track a checked-in CHANGELOG.md — products and tag-only repos (e.g. Next.js, which ships GitHub releases but no CHANGELOG file) return none. For large files, pass `changelog_tokens` (recommended brackets: 2000 / 5000 / 10000 / 20000) to get a heading-aligned slice, then chain via the returned `nextOffset`. Every response reports `totalTokens` so you can budget calls upfront.\n- **A curated topic feed** → `list_collections` to discover, `get_collection_releases` for the interleaved cross-org feed.\n\n### Step 3: Compare products (no built-in tool)\n\nThere is no `compare_products` or `summarize_changes` tool on the hosted server. To compare, fetch each product separately (`get_catalog_entry` for metadata, `get_latest_releases` for recent activity) and synthesize the comparison yourself. Both products must be indexed — if one isn't found, say which is missing rather than guessing.\n\n### Step 4: Present results\n\n- Lead with what answers the user's question.\n- Include version numbers and dates when available.\n- Quote key changes from the release notes (keep quotes short).\n- If results are sparse, say the product may not be fully indexed yet — don't fabricate release info.\n\n## Guidelines\n\n- Pass the user's full question into query parameters for better relevance.\n- For time windows, use `since` / `until` on `get_latest_releases` and `search` (relative shorthand like `\"90d\"` or ISO dates).\n- The `kind` filter (`platform|sdk|mobile|desktop|docs|integration|tool`) behaves differently by surface: on **release** results a source inherits its parent product's kind, so `kind: \"sdk\"` returns content under any SDK product; on **catalog** results it matches the row's own kind only. Reach for it when a query is explicitly scoped to one kind (\"which SDKs shipped this week\").\n- If a product isn't found, say so clearly — don't invent releases.\n",
  "analyzing-releases/SKILL.md": "---\nname: analyzing-releases\ndescription: >\n  Analyze release trends across multiple companies to produce competitive\n  intelligence. Use when asked to compare companies, analyze a market segment,\n  identify industry trends, forecast upcoming releases, or answer questions\n  like \"what is X shipping lately\" or \"how does X compare to Y.\" Also triggers\n  on requests for competitive landscape analysis, feature gap analysis, or\n  release velocity comparisons.\n---\n\n# Analyzing Releases\n\nTurn changelog data into competitive intelligence by analyzing release patterns across a cohort of related companies.\n\nThis is a **reader** workflow — it uses only the public, unauthenticated tools. There is no AI summarize/compare tool on the hosted MCP and no `summary`/`compare` command in the CLI; you fetch the raw release data and synthesize the analysis yourself.\n\n## Tools for each step\n\n| Operation | CLI (reader) | MCP tool |\n|-----------|--------------|----------|\n| Find what's indexed for a company | `releases search <company> --json` | `search` (with `type: [\"orgs\",\"catalog\"]`) |\n| List a company's sources | `releases list --query <company> --json` | `list_catalog` (scope with `organization`) |\n| Latest releases (source or org) | `releases tail <slug> --json` · `releases tail --org <org> --json` | `get_latest_releases` (`organization` / `product`, `since`/`until`) |\n| Keyword/semantic release search | `releases search <query> --json` | `search` with `type: [\"releases\"]` |\n| Read one release in full | `releases get <rel_id> --json` | `get_release` |\n| Read a tracked CHANGELOG slice | `releases admin source changelog <slug> --tokens <n>` (key-gated; readers use MCP) | `get_catalog_entry` with `changelog_tokens` / `changelog_offset` (keyless) |\n\nAll releases are indexed already — you don't need to (and as a reader can't) trigger fetches. If a company isn't in the registry at all, say so rather than trying to onboard it; onboarding is an operator task.\n\n## Workflow\n\n### 1. Define the cohort\n\nPick 3-6 companies in the same competitive space. Good cohorts share a common buyer or technical layer (e.g., developer databases, frontend frameworks, observability tools).\n\n### 2. See what's indexed\n\nResolve each company with `search` (or `releases search`). For discovery-style cohorts (\"find observability vendors with edge offerings\"), `search` with `type: [\"orgs\",\"catalog\"]` is vector-backed and matches on description and category — better than a slug-substring `list_catalog --query`. If a company isn't found, note it as a gap rather than fabricating data.\n\n### 3. Pull latest releases with dates\n\nGet structured release data per source or per org. Scope by `organization` for a whole-company view, or by a single source/product for a narrower one. Use a `since` window (e.g. `\"6m\"`) or a count limit to bound the set. Dates are what you'll count for velocity, so keep them.\n\n### 4. Search and cross-reference\n\nSearch across all indexed releases to find a specific feature, breaking change, or pattern. Release search is hybrid (lexical + semantic) by default, so natural-language queries like \"auth refresh tokens\" or \"cold start improvements\" work without exact keyword matches. Pass `mode: \"lexical\"` (CLI `--mode lexical`) when you need strict keyword behavior.\n\n**Result shape:** every hit carries a `kind` discriminator:\n\n- `kind: \"release\"` — a normal release row; use it directly.\n- `kind: \"changelog_chunk\"` — a passage from a stored CHANGELOG.md file. The hit nests the payload under `chunk`: `chunk.source.slug`, `chunk.file_path`, `chunk.offset`, `chunk.length`. Chain into `get_catalog_entry({ identifier: chunk.source.slug, changelog_path: chunk.file_path, changelog_offset: chunk.offset, changelog_limit: chunk.length * 3 })` to read the surrounding section before quoting it — `changelog_path` is what routes monorepos with multiple CHANGELOG files to the right one. Chunk hits often surface older or more granular notes than what's in the indexed release rows, so they're useful for \"when did X first ship\" questions.\n\n### 5. Synthesize\n\nCombine the raw data into a structured analysis:\n\n- **Release velocity table** — releases per company over the window, cadence pattern\n- **Trends adopted across the board** — features 3+ companies shipped in the same window\n- **Differentiating bets** — what each company is investing in that others aren't\n- **Gaps** — what competitors shipped that a given company hasn't\n- **Forecasts** — predictions grounded in pre-release tracks, deprecations, and trajectory\n\n## Output\n\nAsk the user where to save the analysis, or use your best judgment based on the project's conventions. Include a short \"Process Notes\" section listing the exact commands/tools used, so the analysis is reproducible.\n\n## Important\n\n- Focus on what companies shipped. If a source has noisy data (blog posts mixed in, missing dates), work around it silently — don't pad the report with source-quality commentary unless a company had to be substantially excluded.\n- Fill data gaps with web fetches: list a source to get release URLs, then WebFetch to spot-check pages for a missing date, version, or detail.\n- For velocity counting, lean on the dated rows from `get_latest_releases` / `releases tail --json`.\n- Comparison and summarization are yours to synthesize from raw release data — there is no built-in tool that does it for you.\n",
  "creating-releases-json/SKILL.md": "---\nname: creating-releases-json\ndescription: >-\n  Create or update a releases.json manifest so registries and agents can find\n  where a company or project publishes its release notes. Use this whenever\n  someone wants to \"list our product on Releases\", \"add a releases.json\", \"get\n  indexed on Releases Index\", \"here's our website, make us a manifest\", declare a\n  changelog / updates page / RSS feed / GitHub releases / App Store listing /\n  CHANGELOG for discovery, publish a /.well-known/releases.json, or edit an\n  existing one — even if they don't say \"releases.json\" by name. The usual input\n  is just a company website or domain (no codebase required); the manifest is a\n  small, schema-validated file the owner hosts on their domain or repo. This\n  skill discovers the real publish locations, models products without\n  over-fragmenting, writes the correctly-scoped file, validates it locally, and\n  guides publishing it.\n---\n\n# Creating a releases.json manifest\n\n`releases.json` is a small, owner-declared file that states **what products a\ncompany ships and where it publishes release notes** — a changelog, an updates\npage, an RSS/Atom feed, GitHub Releases, an App Store listing, or a hosted\n`CHANGELOG` file. Any registry or agent that reads the format (starting with\n[releases.sh](https://releases.sh)) learns where the release notes live directly\nfrom the owner instead of guessing.\n\n**Authority comes from where the file lives, not from what it claims.** A file at\n`https://{domain}/.well-known/releases.json` speaks for that whole company; a\n`releases.json` at a repository root speaks only for that repo. That is the entire\ntrust model — if you can publish the file at the URL, you can declare what it says.\n\nYour job with this skill: figure out which scope applies, discover the locations\nwhere release notes **actually** live (never invent them), model the company's\nproducts without over-fragmenting, write a correctly-shaped file, validate it, and\nhelp get it published.\n\n## How you'll be asked to run this\n\nMost of the time there is **no codebase** — someone just says *\"here's our website,\nmake us a releases.json\"*. That's the primary path: you work from the live site (and\nGitHub org), browsing to find where updates are published, and you hand back a finished\nfile plus instructions on where to host it. You cannot commit it for them.\n\nLess often you're working **inside a repo** — the one that serves the company's site, or\na single product/library repo — in which case you can also read the codebase and write\nthe file into place. Both paths use the same steps below; only Step 1 (scope) and Step 5\n(publish) differ.\n\n## The one rule that matters most\n\n**Only declare locations that really exist and respond.** The manifest states plain\nfacts about where updates are published. A guessed or aspirational URL is worse than\nomitting it — it creates a broken source. Before writing any locator, confirm the URL\nresolves (fetch it, or check it against the codebase/site). If you cannot verify a\nlocation, leave it out and say so.\n\n## Step 1 — Choose the scope\n\nThere are two scopes. They share one schema but declare different things:\n\n| Scope      | Lives at                                                 | Declares                                                    |\n| ---------- | -------------------------------------------------------- | ----------------------------------------------------------- |\n| **Domain** | `https://{domain}/.well-known/releases.json`             | Company identity, `products[]`, and top-level `releases[]`  |\n| **Repo**   | `releases.json` at a repository root                     | A `product` binding + where **this repo's** releases land   |\n\n**Default to domain scope** — it's what \"here's our website, make us a manifest\" wants, and\nit's the only scope that can describe the whole company and multiple products. Choose repo\nscope only when you're clearly operating inside one product/library repo and the goal is to\nbind *that repo* to a product. A repo file **cannot** declare company identity; a domain\nfile cannot speak for a repo it doesn't host. If genuinely unsure, ask which one they want.\n\n## Step 2 — Discover the real publish locations\n\nSearch the codebase and the company's site for every place product updates are\npublished. Look for, and **verify each one responds**:\n\n- **Changelog / what's-new / updates pages** — `/changelog`, `/whats-new`,\n  `/releases`, `updates.<domain>`, a \"Product updates\" blog category.\n- **RSS/Atom feeds** — often linked from the changelog page's `<head>`\n  (`<link rel=\"alternate\" type=\"application/rss+xml\">`), or a Canny/Beamer/Headway feed.\n- **GitHub repos with Releases** — repos under the org that cut tagged releases or keep a\n  `CHANGELOG.md`. Use `owner/repo`.\n- **App Store listings** — for mobile apps whose release notes live in the store.\n- **Hosted `CHANGELOG` documents** — a raw `CHANGELOG.md` served at a URL (not in GitHub).\n\nMap each finding to a locator key:\n\n| Key        | Use it for                                                        | Notes                                                        |\n| ---------- | ----------------------------------------------------------------- | ------------------------------------------------------------ |\n| `url`      | The page a **person** reads — changelog / updates / what's-new    | The canonical human page. `https://` only.                   |\n| `feed`     | The RSS/Atom feed machines follow                                 | May be third-party-hosted (Canny, Beamer…). `https://` only. |\n| `github`   | A repo whose Releases are the record                              | `\"owner/repo\"`. In a **repo file only**, `\"self\"` = this repo. |\n| `appstore` | An App Store listing URL                                          | `https://` only.                                             |\n| `file`     | A raw changelog document at a URL (hosted `CHANGELOG.md`)         | `https://` only.                                             |\n| `publish`  | `\"push\"` — the owner publishes this changelog; the registry does not poll it | Requires `github` and `path`. See below.          |\n| `path`     | Changelog file or glob inside that repo                            | Only with `publish: \"push\"`. Relative, no `..`.              |\n\nOne `releases[]` entry can combine keys when they describe the **same** source — most\ncommonly `url` + `feed` (the page a human reads and the feed a machine follows for it).\nAdd `\"title\"` to name a location, and `\"canonical\": true` on the single primary entry\nwhen several locations describe one product/repo scope (**at most one canonical per\nscope**).\n\n`source.url` is for humans. If a URL is purely a machine endpoint nobody would visit,\nit belongs in `feed`/`file`, not `url`.\n\n### Direct publishing (`publish: \"push\"`)\n\nUse this when the changelog lives in git and the owner will **push it in** with the\n[publish-changelog GitHub Action](https://releases.sh/docs/integrations/github-actions),\ninstead of the registry polling a feed or a page. It uses the same `releases[]` entry\nas every other locator, with `github` naming the repo:\n\n```json\n{\n  \"github\": \"acme/docs\",\n  \"path\": \"changelog/**/*.mdx\",\n  \"publish\": \"push\"\n}\n```\n\n- `github` is `\"owner/repo\"`, or `\"self\"` in a **repo** file.\n- `path` is the file (`CHANGELOG.md` → Action input `changelog-path`) or glob\n  (`changelog/**/*.mdx` → `changelog-glob`). Relative only.\n- A single file with no wildcard is the usual Keep-a-Changelog case; a glob is\n  directory mode (one MDX/Markdown file per release).\n\nDo **not** invent this for a changelog the registry can already fetch. It is for\nowners who publish on merge. The registry creates the push-fed source only after\nthe domain's ownership claim is verified; until then the locator is recorded and\nleft unmaterialized. `POST /v1/listing/validate` lists the three steps that\nfollow: verify the domain, mint a publish token (Account → Webhooks & API), add\nthe Action pointed at `path`.\n\nA plain `github` entry without `publish` still means \"poll this repo's GitHub\nreleases\". Do not set `publish` on a feed or a page.\n\n## Step 2b — Model products correctly (don't over-fragment)\n\nThis is where agents most often go wrong. **`products[]` is optional, and a manifest with\njust a top-level `releases[]` is often the *right* answer.** Only reach for `products[]`\nwhen the company genuinely ships multiple things that publish releases in *different*\nplaces. The test for whether something deserves its own product entry is simple:\n\n> **Does it have its own release location?** A product earns an entry only if it has a\n> release stream distinct from the company changelog — its own repo, its own feed, its own\n> changelog page, or its own App Store listing.\n\nMarketing structure is **not** release structure. Companies segment their site into\n\"capabilities\", \"solutions\", or \"modules\" for buyers; that segmentation almost never maps\nto distinct release feeds. Follow where the *releases* are published, not how the *site*\nis organized.\n\n**Two anti-patterns to actively avoid:**\n\n- **One product per marketing capability, all pointing at the same changelog.** If you find\n  yourself writing eight products — \"Analytics\", \"Session Replay\", \"Experiment\", …— that all\n  carry the identical `url`/`feed`, stop. Those aren't eight products; they're one company\n  with one changelog. Declare it once in the top-level `releases[]` and drop the redundant\n  product entries. Duplicated locators just dedup back to one source and add noise.\n- **One product per language SDK.** A company with client libraries in Python, JS, Swift,\n  Kotlin, Go, … has **one** developer/SDK offering, not one product per language. Bundle\n  the libraries as multiple `github` locators under a single product (e.g. `\"API & SDKs\"` or\n  `\"SDKs\"`), mark the primary/most-active one `canonical`. If there are more than 8 repos\n  (the per-product cap), list the most active or the monorepo — don't spill into extra\n  products to fit them all.\n\n**When separate products *are* right:** each has its own release location. Vercel is the\nmodel — Next.js (`github: vercel/next.js`), Turborepo (`vercel/turborepo`), the AI SDK\n(`vercel/ai`), and v0 (`v0.app/changelog`) each publish releases independently, so each is\na real product entry with its own `canonical` locator.\n\n**Rule of thumb:** if every product entry you're about to write shares one changelog, you\nwant zero products and one top-level `releases[]`. Add products only for the pieces that\nbreak out into their own release stream.\n\nFor worked before/after examples of all three cases, see `references/modeling-products.md`.\n\n## Step 3 — Write the file\n\nStart from the matching example in `examples/` and adapt it:\n\n- `examples/domain-minimal.json` — the smallest useful file: `version` + `releases[]`.\n- `examples/domain-products.json` — company identity + `products[]` + registry pin.\n- `examples/repo.json` — a repo-root file with a `product` binding and `github: \"self\"`.\n\nRules to honor (the validator in Step 4 enforces all of these):\n\n- **`\"version\": 2` is required.** v1 files are no longer read. `$schema`\n  (`https://releases.sh/schemas/releases.json`) is optional but recommended — it gives\n  editors autocomplete and validation.\n- **Every `releases[]` entry needs ≥1 locator** (`url`/`feed`/`github`/`appstore`/`file`).\n  `publish: \"push\"` is a mode on a `github` locator and also requires `path`.\n- **`url`/`feed`/`appstore`/`file`/`avatar` must be `https://`.** (`website`/`docs`/`support`\n  on a product may be any valid URL.)\n- **Limits:** ≤ 24 products, ≤ 8 locations per product, and ≤ 32 locations per file total\n  (top-level `releases[]` plus every product's `releases[]` combined).\n- **Don't over-declare identity.** `name`, `description`, `category`, `tags`, `avatar`,\n  `social` shape how the org appears but are all optional — the locations are the point.\n  Fill them only from facts you can confirm.\n- **Domain scope is flat** — no `org` wrapper; the root object *is* the org. Only a domain\n  file may use `products[]`, `name`, `avatar`, `tags`. Only a repo file may use `product`\n  (singular) and `github: \"self\"`.\n- **Products carry a fixed, small set of fields** and nothing else — the schema is strict and\n  rejects unknown keys. A product may have: `name` (required), `slug`, `kind`, `category`,\n  `description`, `website`, `docs`, `support`, `social`, `tags`, `archived`, `releases`.\n  Put company-wide tags at the root; use a product's `tags` only for labels specific to that\n  product. Any key outside this set (or the org-only fields like `products`/`avatar`) fails\n  validation.\n- **Taxonomy is advisory.** `category`, `kind`, `tags` are suggestions; unrecognized values\n  are ignored by the registry, never an error. Don't agonize over exact values.\n\n**Pinning (optional).** If the org/product is already in a registry and you want the file\nbound to exact records instead of matched by URL, add a `registries` block. IDs live on the\norg/product pages. The block is namespaced so other registries can coexist:\n\n```json\n\"registries\": { \"releases.sh\": { \"org\": \"org_abc123\" } }\n```\n\n(In a repo file, use `\"product\": \"prd_…\"` instead.) Unknown registries/keys are ignored.\n\n## Step 4 — Validate locally\n\nRun the bundled zero-dependency validator (Node 18+ or Bun, no install) — it checks the\nfull contract, including rules the plain JSON Schema can't express (at-least-one-locator,\nat-most-one-canonical, the 32-total cap):\n\n```bash\nnode <skill-dir>/scripts/validate.mjs path/to/releases.json\n```\n\nIt auto-detects domain vs repo scope; pass `--scope domain|repo` to force it. A `✓` with\nexit code 0 means valid; a `✗` lists every problem with a JSON path. Fix and re-run until\nit passes. The canonical schema (kept in sync at\n`https://releases.sh/schemas/releases.json`, snapshot at `references/schema.json`) is the\ntie-breaker if anything is ambiguous.\n\nAlso confirm the file is syntactically clean JSON and, if you added `$schema`, that it points\nat `https://releases.sh/schemas/releases.json`.\n\n**If you can't run scripts** (for example, you loaded this skill over MCP in a chat app with no\nshell): check the file by hand against `references/schema.json` and the three cross-field rules\nabove, and tell the owner to run `POST /v1/listing/validate` (Step 5) once it's published.\n\n## Step 5 — Publish and confirm it's live\n\n**If you don't have the repo** (the common \"here's our website\" case), you can't publish it\nfor them — hand back the finished file and tell them exactly where it goes:\n\n- Save the file where they can grab it and tell them its target URL:\n  `https://{domain}/.well-known/releases.json`.\n- Explain the one requirement: it must be served at that exact path, over HTTPS, with\n  `Content-Type: application/json` and no auth wall or redirect. How they do that depends on\n  their host (a `public/.well-known/` directory for most static/Next.js sites, an app route,\n  or their CDN's static-file rules — the same mechanism that serves their `robots.txt`).\n- Then Step 2 of the confirmation below is something *they* run after deploying.\n\n**If you do have the repo,** write it into place:\n\n- **Domain scope:** wherever that project serves `/.well-known/` — e.g. Next.js\n  `public/.well-known/releases.json`, a static site's public root, or an app route serving\n  that exact path. Match how it already serves `robots.txt`.\n- **Repo scope:** commit `releases.json` at the repository root.\n\nAfter it's deployed and publicly reachable, confirm it end-to-end:\n\n1. Fetch the live URL and check it returns HTTP 200 with valid JSON (no auth wall, no HTML\n   redirect):\n   ```bash\n   curl -fsSL https://{domain}/.well-known/releases.json | node <skill-dir>/scripts/validate.mjs /dev/stdin\n   ```\n2. **Optional — ask Releases Index to validate the live domain** (no account needed; reads the\n   file the same way the daily sweep will):\n   ```bash\n   curl -fsS -X POST https://api.releases.sh/v1/listing/validate \\\n     -H 'content-type: application/json' \\\n     -d '{\"domain\":\"{domain}\"}'\n   ```\n   The response previews the parsed identity, per-product location counts, and how each\n   locator will be tiered. A `publish: \"push\"` locator comes back as `kind: \"push\"`\n   with `setupSteps` (verify the domain, mint a publish token, add the Action). This\n   is read-only — it does **not** create a listing.\n\nThen stop. There's nothing else to run: the registry re-reads the file on a regular sweep,\nso future edits are picked up automatically. Feeds/GitHub/App Store locations go live after a\nquick automated check; plain web pages are reviewed by a person before any crawling starts.\nThe file is fill-if-empty and never overwrites curator decisions, so it's safe to leave in place.\n\n## Updating an existing manifest\n\n1. Read the current file and run it through `scripts/validate.mjs` first to see where it stands\n   (it may predate a rule).\n2. Re-verify that every already-declared location still responds; drop dead ones.\n3. Add newly-found locations, keeping within the caps and the one-canonical rule.\n4. If it's still a v1 file (`\"version\": 1` or profile-only fields like a nested `org`),\n   **rewrite it to v2** — v1 is no longer read. Keep only what maps to the v2 shape above.\n5. Validate again, then redeploy. No re-submission step is needed.\n\n## Reference\n\n- `references/modeling-products.md` — worked good/bad examples of the product-modeling rules\n  in Step 2b (capability sprawl, one-product-per-SDK, and when separate products are right).\n  Read it when a company has many offerings and you're unsure how to split them.\n- `references/schema.json` — the bundled JSON Schema snapshot (canonical:\n  `https://releases.sh/schemas/releases.json`).\n- `examples/` — minimal domain, full domain-with-products, and repo-root files.\n- Owner-facing prose docs: `https://releases.sh/docs/listing` (fuller narrative + a\n  copy-paste agent prompt; this skill is the operational version of that guidance).\n- To get an org into the registry in the first place (if it isn't listed yet), the owner can\n  submit a changelog URL at `https://releases.sh/submit`, or the live-domain\n  `POST /v1/listing/validate` → `activate` lane can create a listing from a published file.\n",
  "creating-releases-json/examples/domain-minimal.json": "{\n  \"$schema\": \"https://releases.sh/schemas/releases.json\",\n  \"version\": 2,\n  \"releases\": [{ \"url\": \"https://updates.acme.com\", \"feed\": \"https://updates.acme.com/rss.xml\" }]\n}\n",
  "creating-releases-json/examples/domain-products.json": "{\n  \"$schema\": \"https://releases.sh/schemas/releases.json\",\n  \"version\": 2,\n  \"name\": \"Acme\",\n  \"description\": \"CI for teams that ship.\",\n  \"category\": \"developer-tools\",\n  \"tags\": [\"ci\", \"observability\"],\n  \"avatar\": \"https://acme.com/logo.png\",\n  \"social\": { \"github\": \"acme\", \"twitter\": \"acmehq\" },\n  \"products\": [\n    {\n      \"name\": \"Acme Cloud\",\n      \"description\": \"Managed CI runners.\",\n      \"website\": \"https://acme.com/cloud\",\n      \"docs\": \"https://docs.acme.com/cloud\",\n      \"tags\": [\"ci\", \"cloud\"],\n      \"releases\": [\n        {\n          \"url\": \"https://acme.com/whats-new\",\n          \"feed\": \"https://acme.com/whats-new/rss.xml\",\n          \"canonical\": true\n        },\n        { \"github\": \"acme/cloud-sdk\" }\n      ]\n    },\n    { \"name\": \"Acme Legacy Agent\", \"archived\": true }\n  ],\n  \"releases\": [{ \"url\": \"https://updates.acme.com\" }],\n  \"registries\": {\n    \"releases.sh\": { \"org\": \"org_abc123\" }\n  }\n}\n",
  "creating-releases-json/examples/domain-push.json": "{\n  \"$schema\": \"https://releases.sh/schemas/releases.json\",\n  \"version\": 2,\n  \"name\": \"Acme\",\n  \"releases\": [\n    {\n      \"github\": \"acme/docs\",\n      \"path\": \"changelog/**/*.mdx\",\n      \"publish\": \"push\",\n      \"title\": \"Product changelog\"\n    }\n  ]\n}\n",
  "creating-releases-json/examples/repo.json": "{\n  \"$schema\": \"https://releases.sh/schemas/releases.json\",\n  \"version\": 2,\n  \"product\": { \"name\": \"Acme Cloud\", \"slug\": \"acme-cloud\" },\n  \"releases\": [{ \"url\": \"https://acme.com/whats-new\", \"canonical\": true }, { \"github\": \"self\" }]\n}\n",
  "creating-releases-json/references/modeling-products.md": "# Modeling products without over-fragmenting\n\nThe single most common mistake when authoring a `releases.json` is turning a company's\n**marketing structure** into a pile of product entries. The registry groups by **where\nreleases are published**, so the only question that matters for each candidate product is:\n\n> Does it have its own release location (repo / feed / changelog page / App Store listing)\n> that differs from the company changelog?\n\nIf the answer is no, it does not belong in `products[]`.\n\n---\n\n## Anti-pattern 1 — a product per marketing capability\n\nA site markets one platform as many \"capabilities\" or \"solutions\". An agent faithfully\nmirrors the nav into products, and every one points at the **same** changelog:\n\n```jsonc\n// DON'T — eight products, one changelog, zero added information\n{\n  \"version\": 2,\n  \"name\": \"Amplitude\",\n  \"releases\": [{ \"url\": \"https://amplitude.com/releases\", \"feed\": \"https://amplitude.com/releases/feed.xml\", \"canonical\": true }],\n  \"products\": [\n    { \"name\": \"Product Analytics\", \"releases\": [{ \"url\": \"https://amplitude.com/releases\", \"canonical\": true }] },\n    { \"name\": \"Session Replay\",    \"releases\": [{ \"url\": \"https://amplitude.com/releases\", \"canonical\": true }] },\n    { \"name\": \"Experiment\",        \"releases\": [{ \"url\": \"https://amplitude.com/releases\", \"canonical\": true }] },\n    { \"name\": \"Data\",              \"releases\": [{ \"url\": \"https://amplitude.com/releases\", \"canonical\": true }] }\n    // …four more, all identical\n  ]\n}\n```\n\nEvery product's locator is the top-level changelog. In the registry these dedup back to one\nsource — the products carry no release information the top-level array didn't already have.\n\n```jsonc\n// DO — one company, one changelog\n{\n  \"version\": 2,\n  \"name\": \"Amplitude\",\n  \"description\": \"Digital analytics platform.\",\n  \"releases\": [{ \"url\": \"https://amplitude.com/releases\", \"feed\": \"https://amplitude.com/releases/feed.xml\", \"canonical\": true }]\n}\n```\n\nIf a capability later gets its *own* feed or repo, add it as a product **then** — when it\nhas a distinct release location to point at.\n\n---\n\n## Anti-pattern 2 — a product per language SDK\n\nA company publishes client libraries across languages. Each is a separate GitHub repo, so\nan agent makes each a product:\n\n```jsonc\n// DON'T — one product per language\n\"products\": [\n  { \"name\": \"TypeScript SDK\", \"releases\": [{ \"github\": \"acme/acme-typescript\" }] },\n  { \"name\": \"Python SDK\",     \"releases\": [{ \"github\": \"acme/acme-python\" }] },\n  { \"name\": \"Swift SDK\",      \"releases\": [{ \"github\": \"acme/acme-swift\" }] },\n  { \"name\": \"Go SDK\",         \"releases\": [{ \"github\": \"acme/acme-go\" }] }\n]\n```\n\nThese are one developer offering with several distribution targets, not four products.\nBundle the repos as locators under a single product and mark the primary one `canonical`:\n\n```jsonc\n// DO — one SDK product, many github locators\n\"products\": [\n  {\n    \"name\": \"API & SDKs\",\n    \"description\": \"The Acme API and its official client libraries.\",\n    \"docs\": \"https://acme.com/docs\",\n    \"releases\": [\n      { \"github\": \"acme/acme-typescript\", \"canonical\": true },\n      { \"github\": \"acme/acme-python\" },\n      { \"github\": \"acme/acme-swift\" },\n      { \"github\": \"acme/acme-go\" }\n    ]\n  }\n]\n```\n\nA product allows at most 8 release locations. With more repos than that, list the most\nactive ones (or a monorepo) rather than spilling into extra products to fit them all.\n\n---\n\n## When separate products ARE correct\n\nEach genuinely has its own, distinct release stream. Vercel is the reference shape — every\nproduct publishes releases in its own place, so each is a real entry:\n\n```jsonc\n\"products\": [\n  { \"name\": \"Next.js\",    \"website\": \"https://nextjs.org\",     \"releases\": [{ \"github\": \"vercel/next.js\",   \"canonical\": true }, { \"url\": \"https://nextjs.org/blog\" }] },\n  { \"name\": \"Turborepo\",  \"website\": \"https://turborepo.com\",  \"releases\": [{ \"github\": \"vercel/turborepo\", \"canonical\": true }] },\n  { \"name\": \"AI SDK\",     \"website\": \"https://ai-sdk.dev\",     \"releases\": [{ \"github\": \"vercel/ai\",        \"canonical\": true }] },\n  { \"name\": \"v0\",         \"website\": \"https://v0.app\",         \"releases\": [{ \"url\": \"https://v0.app/changelog\", \"canonical\": true }] }\n]\n```\n\nThe distinguishing feature isn't that these are \"big\" products — it's that each has a\nrelease location the others don't share.\n\n---\n\n## A quick self-check before you finish\n\n- Do two or more products carry the **identical** `url`/`feed`? Collapse them — that content\n  belongs in the top-level `releases[]`.\n- Is there a product per programming language? Merge into one SDK product.\n- Does every product entry have at least one locator the top-level array doesn't already\n  cover? If not, you probably don't need `products[]` at all.\n- Did you put a non-schema field on a product? Products accept only `name`, `slug`, `kind`,\n  `category`, `description`, `website`, `docs`, `support`, `social`, `tags`, `archived`,\n  `releases`. Product `tags` are for labels specific to that product; company-wide tags go at\n  the root. Anything else (e.g. `products`/`avatar`, which are org-only) fails validation.\n",
  "creating-releases-json/references/schema.json": "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://releases.sh/schemas/releases.json\",\n  \"title\": \"releases.json v2 manifest\",\n  \"description\": \"Owner-declared products and release locations. Host at https://{domain}/.well-known/releases.json (org scope) or in a repository root as releases.json (repository scope).\",\n  \"anyOf\": [\n    {\n      \"type\": \"object\",\n      \"properties\": {\n        \"$schema\": {\n          \"type\": \"string\",\n          \"format\": \"uri\"\n        },\n        \"version\": {\n          \"type\": \"number\",\n          \"const\": 2\n        },\n        \"registries\": {\n          \"type\": \"object\",\n          \"properties\": {\n            \"releases.sh\": {\n              \"type\": \"object\",\n              \"properties\": {\n                \"org\": {\n                  \"type\": \"string\",\n                  \"pattern\": \"^org_[A-Za-z0-9]+$\"\n                },\n                \"product\": {\n                  \"type\": \"string\",\n                  \"pattern\": \"^prd_[A-Za-z0-9]+$\"\n                },\n                \"verification\": {\n                  \"type\": \"string\",\n                  \"minLength\": 1,\n                  \"maxLength\": 500\n                }\n              },\n              \"additionalProperties\": {}\n            }\n          },\n          \"additionalProperties\": {}\n        },\n        \"releases\": {\n          \"maxItems\": 32,\n          \"type\": \"array\",\n          \"items\": {\n            \"type\": \"object\",\n            \"properties\": {\n              \"url\": {\n                \"type\": \"string\",\n                \"format\": \"uri\",\n                \"pattern\": \"^https:\\\\/\\\\/.*\"\n              },\n              \"feed\": {\n                \"type\": \"string\",\n                \"format\": \"uri\",\n                \"pattern\": \"^https:\\\\/\\\\/.*\"\n              },\n              \"appstore\": {\n                \"type\": \"string\",\n                \"format\": \"uri\",\n                \"pattern\": \"^https:\\\\/\\\\/.*\"\n              },\n              \"file\": {\n                \"type\": \"string\",\n                \"format\": \"uri\",\n                \"pattern\": \"^https:\\\\/\\\\/.*\"\n              },\n              \"title\": {\n                \"type\": \"string\",\n                \"minLength\": 1,\n                \"maxLength\": 200\n              },\n              \"canonical\": {\n                \"type\": \"boolean\"\n              },\n              \"publish\": {\n                \"type\": \"string\",\n                \"const\": \"push\"\n              },\n              \"path\": {\n                \"type\": \"string\",\n                \"minLength\": 1,\n                \"maxLength\": 200,\n                \"pattern\": \"^(?!\\\\/)(?!.*(?:^|\\\\/)\\\\.\\\\.(?:\\\\/|$))[A-Za-z0-9._~@%+\\\\-/*?[\\\\]{}]+$\"\n              },\n              \"github\": {\n                \"type\": \"string\",\n                \"pattern\": \"^[A-Za-z0-9._-]+\\\\/[A-Za-z0-9._-]+$\"\n              }\n            },\n            \"additionalProperties\": false\n          }\n        },\n        \"name\": {\n          \"type\": \"string\",\n          \"minLength\": 1,\n          \"maxLength\": 120\n        },\n        \"description\": {\n          \"type\": \"string\",\n          \"maxLength\": 2000\n        },\n        \"category\": {\n          \"type\": \"string\",\n          \"minLength\": 1,\n          \"maxLength\": 120\n        },\n        \"avatar\": {\n          \"type\": \"string\",\n          \"format\": \"uri\",\n          \"pattern\": \"^https:\\\\/\\\\/.*\"\n        },\n        \"tags\": {\n          \"maxItems\": 50,\n          \"type\": \"array\",\n          \"items\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 60\n          }\n        },\n        \"social\": {\n          \"type\": \"object\",\n          \"propertyNames\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 40\n          },\n          \"additionalProperties\": {\n            \"type\": \"string\",\n            \"minLength\": 1,\n            \"maxLength\": 200\n          }\n        },\n        \"products\": {\n          \"maxItems\": 24,\n          \"type\": \"array\",\n          \"items\": {\n            \"type\": \"object\",\n            \"properties\": {\n              \"name\": {\n                \"type\": \"string\",\n                \"minLength\": 1,\n                \"maxLength\": 120\n              },\n              \"slug\": {\n                \"type\": \"string\",\n                \"minLength\": 1,\n                \"maxLength\": 120\n              },\n              \"kind\": {\n                \"type\": \"string\",\n                \"minLength\": 1,\n                \"maxLength\": 120\n              },\n              \"category\": {\n                \"type\": \"string\",\n                \"minLength\": 1,\n                \"maxLength\": 120\n              },\n              \"description\": {\n                \"type\": \"string\",\n                \"maxLength\": 2000\n              },\n              \"website\": {\n                \"type\": \"string\",\n                \"format\": \"uri\"\n              },\n              \"docs\": {\n                \"type\": \"string\",\n                \"format\": \"uri\"\n              },\n              \"support\": {\n                \"type\": \"string\",\n                \"format\": \"uri\"\n              },\n              \"social\": {\n                \"type\": \"object\",\n                \"propertyNames\": {\n                  \"type\": \"string\",\n                  \"minLength\": 1,\n                  \"maxLength\": 40\n                },\n                \"additionalProperties\": {\n                  \"type\": \"string\",\n                  \"minLength\": 1,\n                  \"maxLength\": 200\n                }\n              },\n              \"tags\": {\n                \"maxItems\": 50,\n                \"type\": \"array\",\n                \"items\": {\n                  \"type\": \"string\",\n                  \"minLength\": 1,\n                  \"maxLength\": 60\n                }\n              },\n              \"archived\": {\n                \"type\": \"boolean\"\n              },\n              \"releases\": {\n                \"maxItems\": 8,\n                \"type\": \"array\",\n                \"items\": {\n                  \"type\": \"object\",\n                  \"properties\": {\n                    \"url\": {\n                      \"type\": \"string\",\n                      \"format\": \"uri\",\n                      \"pattern\": \"^https:\\\\/\\\\/.*\"\n                    },\n                    \"feed\": {\n                      \"type\": \"string\",\n                      \"format\": \"uri\",\n                      \"pattern\": \"^https:\\\\/\\\\/.*\"\n                    },\n                    \"appstore\": {\n                      \"type\": \"string\",\n                      \"format\": \"uri\",\n                      \"pattern\": \"^https:\\\\/\\\\/.*\"\n                    },\n                    \"file\": {\n                      \"type\": \"string\",\n                      \"format\": \"uri\",\n                      \"pattern\": \"^https:\\\\/\\\\/.*\"\n                    },\n                    \"title\": {\n                      \"type\": \"string\",\n                      \"minLength\": 1,\n                      \"maxLength\": 200\n                    },\n                    \"canonical\": {\n                      \"type\": \"boolean\"\n                    },\n                    \"publish\": {\n                      \"type\": \"string\",\n                      \"const\": \"push\"\n                    },\n                    \"path\": {\n                      \"type\": \"string\",\n                      \"minLength\": 1,\n                      \"maxLength\": 200,\n                      \"pattern\": \"^(?!\\\\/)(?!.*(?:^|\\\\/)\\\\.\\\\.(?:\\\\/|$))[A-Za-z0-9._~@%+\\\\-/*?[\\\\]{}]+$\"\n                    },\n                    \"github\": {\n                      \"type\": \"string\",\n                      \"pattern\": \"^[A-Za-z0-9._-]+\\\\/[A-Za-z0-9._-]+$\"\n                    }\n                  },\n                  \"additionalProperties\": false\n                }\n              }\n            },\n            \"required\": [\"name\"],\n            \"additionalProperties\": false\n          }\n        }\n      },\n      \"required\": [\"version\"],\n      \"additionalProperties\": false\n    },\n    {\n      \"type\": \"object\",\n      \"properties\": {\n        \"$schema\": {\n          \"type\": \"string\",\n          \"format\": \"uri\"\n        },\n        \"version\": {\n          \"type\": \"number\",\n          \"const\": 2\n        },\n        \"registries\": {\n          \"type\": \"object\",\n          \"properties\": {\n            \"releases.sh\": {\n              \"type\": \"object\",\n              \"properties\": {\n                \"org\": {\n                  \"type\": \"string\",\n                  \"pattern\": \"^org_[A-Za-z0-9]+$\"\n                },\n                \"product\": {\n                  \"type\": \"string\",\n                  \"pattern\": \"^prd_[A-Za-z0-9]+$\"\n                },\n                \"verification\": {\n                  \"type\": \"string\",\n                  \"minLength\": 1,\n                  \"maxLength\": 500\n                }\n              },\n              \"additionalProperties\": {}\n            }\n          },\n          \"additionalProperties\": {}\n        },\n        \"product\": {\n          \"type\": \"object\",\n          \"properties\": {\n            \"name\": {\n              \"type\": \"string\",\n              \"minLength\": 1,\n              \"maxLength\": 120\n            },\n            \"slug\": {\n              \"type\": \"string\",\n              \"minLength\": 1,\n              \"maxLength\": 120\n            }\n          },\n          \"required\": [\"name\"],\n          \"additionalProperties\": false\n        },\n        \"releases\": {\n          \"maxItems\": 32,\n          \"type\": \"array\",\n          \"items\": {\n            \"type\": \"object\",\n            \"properties\": {\n              \"url\": {\n                \"type\": \"string\",\n                \"format\": \"uri\",\n                \"pattern\": \"^https:\\\\/\\\\/.*\"\n              },\n              \"feed\": {\n                \"type\": \"string\",\n                \"format\": \"uri\",\n                \"pattern\": \"^https:\\\\/\\\\/.*\"\n              },\n              \"appstore\": {\n                \"type\": \"string\",\n                \"format\": \"uri\",\n                \"pattern\": \"^https:\\\\/\\\\/.*\"\n              },\n              \"file\": {\n                \"type\": \"string\",\n                \"format\": \"uri\",\n                \"pattern\": \"^https:\\\\/\\\\/.*\"\n              },\n              \"title\": {\n                \"type\": \"string\",\n                \"minLength\": 1,\n                \"maxLength\": 200\n              },\n              \"canonical\": {\n                \"type\": \"boolean\"\n              },\n              \"publish\": {\n                \"type\": \"string\",\n                \"const\": \"push\"\n              },\n              \"path\": {\n                \"type\": \"string\",\n                \"minLength\": 1,\n                \"maxLength\": 200,\n                \"pattern\": \"^(?!\\\\/)(?!.*(?:^|\\\\/)\\\\.\\\\.(?:\\\\/|$))[A-Za-z0-9._~@%+\\\\-/*?[\\\\]{}]+$\"\n              },\n              \"github\": {\n                \"anyOf\": [\n                  {\n                    \"type\": \"string\",\n                    \"const\": \"self\"\n                  },\n                  {\n                    \"type\": \"string\",\n                    \"pattern\": \"^[A-Za-z0-9._-]+\\\\/[A-Za-z0-9._-]+$\"\n                  }\n                ]\n              }\n            },\n            \"additionalProperties\": false\n          }\n        }\n      },\n      \"required\": [\"version\"],\n      \"additionalProperties\": false\n    }\n  ]\n}\n",
  "creating-releases-json/scripts/validate.mjs": "#!/usr/bin/env node\n// Validate a releases.json v2 manifest against the releases.sh rules.\n//\n// Zero dependencies — runs under Node 18+ or Bun with no install step, so it\n// works inside any vendor repo. It encodes the full contract, including the\n// three rules the published JSON Schema can't express on its own:\n//   1. every releases[] entry needs at least one locator (url/feed/github/appstore/file)\n//   2. at most one entry per array may be \"canonical\": true\n//   3. a file may declare at most 32 release locations in total (top-level + all products)\n//\n// Usage:\n//   node validate.mjs <path-to-releases.json> [--scope domain|repo]\n//\n// Scope is auto-detected when omitted: a `product` key or `github: \"self\"`\n// means repository scope; otherwise domain (well-known) scope. Exit code is 0\n// when valid, 1 when not (or on a usage/parse error).\n\nimport { readFileSync } from \"node:fs\";\n\nconst MAX_PRODUCTS = 24;\nconst MAX_PRODUCT_RELEASES = 8;\nconst MAX_FILE_RELEASES = 32;\n\nconst GITHUB_REPO = /^[A-Za-z0-9._-]+\\/[A-Za-z0-9._-]+$/;\n// Relative changelog file or glob. No scheme, no leading slash, no `..`.\nconst PUBLISH_PATH =\n  /^(?!\\/)(?!.*(?:^|\\/)\\.\\.(?:\\/|$))[A-Za-z0-9._~@%+\\-/*?[\\]{}]+$/;\nconst ORG_ID = /^org_[A-Za-z0-9]+$/;\nconst PRD_ID = /^prd_[A-Za-z0-9]+$/;\n\nconst errors = [];\nconst err = (path, msg) => errors.push(`${path}: ${msg}`);\n\nconst isObject = (v) => typeof v === \"object\" && v !== null && !Array.isArray(v);\n\nfunction isUrl(v) {\n  if (typeof v !== \"string\") return false;\n  try {\n    new URL(v);\n    return true;\n  } catch {\n    return false;\n  }\n}\nconst isHttpsUrl = (v) => isUrl(v) && v.startsWith(\"https://\");\n\nfunction checkStr(path, v, { min = 0, max = Infinity } = {}) {\n  if (typeof v !== \"string\") return err(path, \"must be a string\");\n  if (v.length < min) err(path, `must be at least ${min} character(s)`);\n  if (v.length > max) err(path, `must be at most ${max} characters`);\n}\n\nfunction checkKnownKeys(path, obj, allowed) {\n  for (const key of Object.keys(obj)) {\n    if (!allowed.includes(key)) err(path, `unknown key \"${key}\" (not allowed here)`);\n  }\n}\n\nfunction checkSocial(path, social) {\n  if (!isObject(social)) return err(path, \"must be an object of handle => value\");\n  for (const [k, v] of Object.entries(social)) {\n    checkStr(`${path}.${k} (key)`, k, { min: 1, max: 40 });\n    checkStr(`${path}.${k}`, v, { min: 1, max: 200 });\n  }\n}\n\nfunction checkTags(path, tags) {\n  if (!Array.isArray(tags)) return err(path, \"must be an array\");\n  if (tags.length > 50) err(path, \"may hold at most 50 tags\");\n  tags.forEach((t, i) => checkStr(`${path}[${i}]`, t, { min: 1, max: 60 }));\n}\n\nfunction checkRegistries(path, reg) {\n  if (!isObject(reg)) return err(path, \"must be an object\");\n  const rsh = reg[\"releases.sh\"];\n  if (rsh === undefined) return; // other registries are allowed and ignored\n  if (!isObject(rsh)) return err(`${path}[\"releases.sh\"]`, \"must be an object\");\n  if (rsh.org !== undefined && !ORG_ID.test(rsh.org))\n    err(`${path}[\"releases.sh\"].org`, 'must match \"org_…\"');\n  if (rsh.product !== undefined && !PRD_ID.test(rsh.product))\n    err(`${path}[\"releases.sh\"].product`, 'must match \"prd_…\"');\n  if (rsh.verification !== undefined)\n    checkStr(`${path}[\"releases.sh\"].verification`, rsh.verification, { min: 1, max: 500 });\n}\n\n// One release-location entry. `allowSelf` toggles github: \"self\" (repo scope only).\nfunction checkRelease(path, entry, allowSelf) {\n  if (!isObject(entry)) return err(path, \"must be an object\");\n  checkKnownKeys(path, entry, [\n    \"url\",\n    \"feed\",\n    \"appstore\",\n    \"file\",\n    \"title\",\n    \"canonical\",\n    \"github\",\n    \"publish\",\n    \"path\",\n  ]);\n\n  for (const key of [\"url\", \"feed\", \"appstore\", \"file\"]) {\n    if (entry[key] !== undefined && !isHttpsUrl(entry[key]))\n      err(`${path}.${key}`, \"must be an https:// URL\");\n  }\n  if (entry.title !== undefined) checkStr(`${path}.title`, entry.title, { min: 1, max: 200 });\n  if (entry.canonical !== undefined && typeof entry.canonical !== \"boolean\")\n    err(`${path}.canonical`, \"must be true or false\");\n  if (entry.github !== undefined) {\n    const ok = GITHUB_REPO.test(entry.github) || (allowSelf && entry.github === \"self\");\n    if (!ok)\n      err(`${path}.github`, allowSelf ? 'must be \"owner/repo\" or \"self\"' : 'must be \"owner/repo\"');\n  }\n\n  if (entry.publish !== undefined && entry.publish !== \"push\")\n    err(`${path}.publish`, 'must be \"push\" when set');\n  if (entry.path !== undefined) {\n    if (typeof entry.path !== \"string\" || !PUBLISH_PATH.test(entry.path) || entry.path.length > 200)\n      err(`${path}.path`, \"must be a relative changelog file or glob (no leading slash, no ..)\");\n  }\n  if (entry.publish === \"push\") {\n    if (!entry.github) err(`${path}.github`, 'is required when publish is \"push\"');\n    if (!entry.path) err(`${path}.path`, 'is required when publish is \"push\"');\n  } else if (entry.path !== undefined) {\n    err(`${path}.path`, 'is only valid together with \"publish\": \"push\"');\n  }\n\n  const hasLocator = entry.url || entry.feed || entry.github || entry.appstore || entry.file;\n  if (!hasLocator) err(path, \"needs at least one locator: url, feed, github, appstore, or file\");\n}\n\nfunction checkReleasesArray(path, arr, { max, allowSelf }) {\n  if (!Array.isArray(arr)) return err(path, \"must be an array\");\n  if (arr.length > max) err(path, `may hold at most ${max} entries`);\n  arr.forEach((entry, i) => checkRelease(`${path}[${i}]`, entry, allowSelf));\n  const canonical = arr.filter((e) => isObject(e) && e.canonical === true).length;\n  if (canonical > 1) err(path, 'at most one entry may be marked \"canonical\": true');\n}\n\nfunction checkProduct(path, p) {\n  if (!isObject(p)) return err(path, \"must be an object\");\n  checkKnownKeys(path, p, [\n    \"name\",\n    \"slug\",\n    \"kind\",\n    \"category\",\n    \"description\",\n    \"website\",\n    \"docs\",\n    \"support\",\n    \"social\",\n    \"tags\",\n    \"archived\",\n    \"releases\",\n  ]);\n  if (p.name === undefined) err(path, 'is missing required \"name\"');\n  else checkStr(`${path}.name`, p.name, { min: 1, max: 120 });\n  for (const key of [\"slug\", \"kind\", \"category\"])\n    if (p[key] !== undefined) checkStr(`${path}.${key}`, p[key], { min: 1, max: 120 });\n  if (p.description !== undefined) checkStr(`${path}.description`, p.description, { max: 2000 });\n  for (const key of [\"website\", \"docs\", \"support\"])\n    if (p[key] !== undefined && !isUrl(p[key])) err(`${path}.${key}`, \"must be a URL\");\n  if (p.social !== undefined) checkSocial(`${path}.social`, p.social);\n  if (p.tags !== undefined) checkTags(`${path}.tags`, p.tags);\n  if (p.archived !== undefined && typeof p.archived !== \"boolean\")\n    err(`${path}.archived`, \"must be true or false\");\n  if (p.releases !== undefined)\n    checkReleasesArray(`${path}.releases`, p.releases, {\n      max: MAX_PRODUCT_RELEASES,\n      allowSelf: false,\n    });\n}\n\nfunction validateDomain(m) {\n  checkKnownKeys(\"(root)\", m, [\n    \"$schema\",\n    \"version\",\n    \"registries\",\n    \"releases\",\n    \"name\",\n    \"description\",\n    \"category\",\n    \"avatar\",\n    \"tags\",\n    \"social\",\n    \"products\",\n  ]);\n  if (m.name !== undefined) checkStr(\"name\", m.name, { min: 1, max: 120 });\n  if (m.description !== undefined) checkStr(\"description\", m.description, { max: 2000 });\n  if (m.category !== undefined) checkStr(\"category\", m.category, { min: 1, max: 120 });\n  if (m.avatar !== undefined && !isHttpsUrl(m.avatar)) err(\"avatar\", \"must be an https:// URL\");\n  if (m.tags !== undefined) checkTags(\"tags\", m.tags);\n  if (m.social !== undefined) checkSocial(\"social\", m.social);\n\n  let totalReleases = 0;\n  if (m.releases !== undefined) {\n    checkReleasesArray(\"releases\", m.releases, { max: MAX_FILE_RELEASES, allowSelf: false });\n    if (Array.isArray(m.releases)) totalReleases += m.releases.length;\n  }\n  if (m.products !== undefined) {\n    if (!Array.isArray(m.products)) err(\"products\", \"must be an array\");\n    else {\n      if (m.products.length > MAX_PRODUCTS)\n        err(\"products\", `may hold at most ${MAX_PRODUCTS} products`);\n      m.products.forEach((p, i) => {\n        checkProduct(`products[${i}]`, p);\n        if (isObject(p) && Array.isArray(p.releases)) totalReleases += p.releases.length;\n      });\n    }\n  }\n  if (totalReleases > MAX_FILE_RELEASES)\n    err(\n      \"(root)\",\n      `at most ${MAX_FILE_RELEASES} release locations total (top-level + every product combined); found ${totalReleases}`,\n    );\n}\n\nfunction validateRepo(m) {\n  checkKnownKeys(\"(root)\", m, [\"$schema\", \"version\", \"registries\", \"product\", \"releases\"]);\n  if (m.product !== undefined) {\n    if (!isObject(m.product)) err(\"product\", \"must be an object\");\n    else {\n      checkKnownKeys(\"product\", m.product, [\"name\", \"slug\"]);\n      if (m.product.name === undefined) err(\"product\", 'is missing required \"name\"');\n      else checkStr(\"product.name\", m.product.name, { min: 1, max: 120 });\n      if (m.product.slug !== undefined)\n        checkStr(\"product.slug\", m.product.slug, { min: 1, max: 120 });\n    }\n  }\n  if (m.releases !== undefined)\n    checkReleasesArray(\"releases\", m.releases, { max: MAX_FILE_RELEASES, allowSelf: true });\n}\n\nfunction detectScope(m) {\n  if (m.product !== undefined) return \"repo\";\n  if (Array.isArray(m.releases) && m.releases.some((e) => isObject(e) && e.github === \"self\"))\n    return \"repo\";\n  if (\n    m.products !== undefined ||\n    m.name !== undefined ||\n    m.avatar !== undefined ||\n    m.tags !== undefined\n  )\n    return \"domain\";\n  return \"domain\"; // a bare { version, releases } file is a valid domain manifest\n}\n\nconst args = process.argv.slice(2);\nconst scopeFlagIdx = args.indexOf(\"--scope\");\nlet scopeFlag = null;\nif (scopeFlagIdx !== -1) {\n  scopeFlag = args[scopeFlagIdx + 1];\n  args.splice(scopeFlagIdx, 2);\n}\nconst filePath = args[0];\n\nif (!filePath) {\n  console.error(\"usage: node validate.mjs <path-to-releases.json> [--scope domain|repo]\");\n  process.exit(1);\n}\nif (scopeFlag && scopeFlag !== \"domain\" && scopeFlag !== \"repo\") {\n  console.error(`invalid --scope \"${scopeFlag}\" (expected \"domain\" or \"repo\")`);\n  process.exit(1);\n}\n\nlet raw;\ntry {\n  raw = readFileSync(filePath, \"utf8\");\n} catch (e) {\n  console.error(`cannot read ${filePath}: ${e.message}`);\n  process.exit(1);\n}\n\nlet manifest;\ntry {\n  manifest = JSON.parse(raw);\n} catch (e) {\n  console.error(`✗ ${filePath} is not valid JSON: ${e.message}`);\n  process.exit(1);\n}\n\nif (!isObject(manifest)) {\n  console.error(\"✗ top level must be a JSON object\");\n  process.exit(1);\n}\n\n// version + $schema/registries are common to both scopes.\nif (manifest.version !== 2)\n  err(\"version\", \"is required and must be the number 2 (v1 files are no longer read)\");\nif (manifest.$schema !== undefined && !isUrl(manifest.$schema)) err(\"$schema\", \"must be a URL\");\nif (manifest.registries !== undefined) checkRegistries(\"registries\", manifest.registries);\n\nconst scope = scopeFlag || detectScope(manifest);\nif (scope === \"repo\") validateRepo(manifest);\nelse validateDomain(manifest);\n\nif (errors.length === 0) {\n  console.log(`✓ ${filePath} is a valid releases.json v2 manifest (${scope} scope).`);\n  process.exit(0);\n}\nconsole.error(`✗ ${filePath} is not valid (${scope} scope). ${errors.length} problem(s):\\n`);\nfor (const e of errors) console.error(`  • ${e}`);\nconsole.error(\n  scopeFlag\n    ? \"\"\n    : `\\n(Scope auto-detected as \"${scope}\". If that's wrong, re-run with --scope domain|repo.)`,\n);\nprocess.exit(1);\n"
};
